class ParquetMetadataConverterTests {

  private static final String CREATED_BY = "parquet-mr version 1.9.0";

  @Test
  void rejectsNonPositiveStatisticsTruncateLength() {
    assertThatThrownBy(() -> new ParquetMetadataConverter(0))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Truncate length should be greater than 0");
    assertThatThrownBy(() -> new ParquetMetadataConverter(-10))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Truncate length should be greater than 0");
  }

  @Test
  void metadataFiltersExposeTheirOffsetsAndStringRepresentation() {
    ParquetMetadataConverter.RangeMetadataFilter range =
        (ParquetMetadataConverter.RangeMetadataFilter) ParquetMetadataConverter.range(10, 20);
    assertThat(range.contains(10)).isTrue();
    assertThat(range.contains(19)).isTrue();
    assertThat(range.contains(20)).isFalse();
    assertThat(range.contains(9)).isFalse();
    assertThat(range).asString().isEqualTo("range(s:10, e:20)");

    ParquetMetadataConverter.OffsetMetadataFilter offsets =
        (ParquetMetadataConverter.OffsetMetadataFilter) ParquetMetadataConverter.offsets(1, 3, 3);
    assertThat(offsets.contains(3)).isTrue();
    assertThat(offsets.contains(2)).isFalse();
    assertThat(ParquetMetadataConverter.NO_FILTER).asString().isEqualTo("NO_FILTER");
    assertThat(ParquetMetadataConverter.SKIP_ROW_GROUPS).asString().isEqualTo("SKIP_ROW_GROUPS");
  }

  @Test
