    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.BYTE_ARRAY))
        .isEqualTo(PrimitiveTypeName.BINARY);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.INT64)).isEqualTo(PrimitiveTypeName.INT64);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.INT32)).isEqualTo(PrimitiveTypeName.INT32);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.BOOLEAN))
        .isEqualTo(PrimitiveTypeName.BOOLEAN);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.FLOAT)).isEqualTo(PrimitiveTypeName.FLOAT);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.DOUBLE))
        .isEqualTo(PrimitiveTypeName.DOUBLE);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.INT96)).isEqualTo(PrimitiveTypeName.INT96);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.FIXED_LEN_BYTE_ARRAY))
        .isEqualTo(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY);

    assertThat(converter.getType(PrimitiveTypeName.INT64)).isEqualTo(org.apache.parquet.format.Type.INT64);
    assertThat(converter.getType(PrimitiveTypeName.INT32)).isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(converter.getType(PrimitiveTypeName.BOOLEAN)).isEqualTo(org.apache.parquet.format.Type.BOOLEAN);
    assertThat(converter.getType(PrimitiveTypeName.BINARY)).isEqualTo(org.apache.parquet.format.Type.BYTE_ARRAY);
    assertThat(converter.getType(PrimitiveTypeName.FLOAT)).isEqualTo(org.apache.parquet.format.Type.FLOAT);
