  @Test
  void convertsEncodingsAndDeduplicatesConvertedEncodingSets() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    for (Encoding formatEncoding : Encoding.values()) {
      assertThat(converter.getEncoding(formatEncoding).name()).isEqualTo(formatEncoding.name());
      assertThat(converter.getEncoding(converter.getEncoding(formatEncoding)))
          .isEqualTo(formatEncoding);
    }

    Set<Encoding> encodings =
        new LinkedHashSet<>(Arrays.asList(Encoding.PLAIN, Encoding.RLE_DICTIONARY, Encoding.PLAIN_DICTIONARY));
    List<org.apache.parquet.format.Encoding> formatted = converter.toFormatEncodings(encodings);
    assertThat(formatted).hasSize(encodings.size());
    assertThat(formatted).isSorted();
    for (Encoding encoding : encodings) {
      assertThat(formatted).contains(converter.getEncoding(encoding));
    }

    Set<Encoding> first = converter.fromFormatEncodings(formatted);
    Set<Encoding> second = converter.fromFormatEncodings(formatted);
    assertThat(first).containsExactlyInAnyOrderElementsOf(encodings);
    assertThat(second).isSameAs(first);
    assertThatThrownBy(() -> first.add(Encoding.BIT_PACKED)).isInstanceOf(UnsupportedOperationException.class);
  }

  @Test
  void convertsEncodingStatsInBothDirections() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    EncodingStats stats = new EncodingStats.Builder()
        .withV2Pages()
        .addDictEncoding(Encoding.PLAIN_DICTIONARY, 2)
        .addDataEncoding(Encoding.RLE_DICTIONARY, 3)
        .addDataEncoding(Encoding.PLAIN, 1)
        .build();

    List<PageEncodingStats> formatStats = converter.convertEncodingStats(stats);
    assertThat(formatStats).hasSize(3);
    assertThat(formatStats)
        .anySatisfy(pageStats -> {
          assertThat(pageStats.getPage_type()).isEqualTo(PageType.DICTIONARY_PAGE);
          assertThat(pageStats.getEncoding()).isEqualTo(org.apache.parquet.format.Encoding.PLAIN_DICTIONARY);
          assertThat(pageStats.getCount()).isEqualTo(2);
        })
        .anySatisfy(pageStats -> {
          assertThat(pageStats.getPage_type()).isEqualTo(PageType.DATA_PAGE_V2);
          assertThat(pageStats.getEncoding()).isEqualTo(org.apache.parquet.format.Encoding.RLE_DICTIONARY);
          assertThat(pageStats.getCount()).isEqualTo(3);
        })
        .anySatisfy(pageStats -> {
          assertThat(pageStats.getPage_type()).isEqualTo(PageType.DATA_PAGE_V2);
          assertThat(pageStats.getEncoding()).isEqualTo(org.apache.parquet.format.Encoding.PLAIN);
          assertThat(pageStats.getCount()).isEqualTo(1);
        });

    EncodingStats roundTripped = converter.convertEncodingStats(formatStats);
    assertThat(roundTripped.usesV2Pages()).isTrue();
    assertThat(roundTripped.getDictionaryEncodings()).containsExactly(Encoding.PLAIN_DICTIONARY);
    assertThat(roundTripped.getNumDictionaryPagesEncodedAs(Encoding.PLAIN_DICTIONARY))
        .isEqualTo(2);
    assertThat(roundTripped.getDataEncodings()).containsExactlyInAnyOrder(Encoding.RLE_DICTIONARY, Encoding.PLAIN);
    assertThat(roundTripped.getNumDataPagesEncodedAs(Encoding.RLE_DICTIONARY))
        .isEqualTo(3);
    assertThat(roundTripped.getNumDataPagesEncodedAs(Encoding.PLAIN)).isEqualTo(1);

    assertThat(converter.convertEncodingStats((EncodingStats) null)).isNull();
    assertThat(converter.convertEncodingStats((List<PageEncodingStats>) null))
        .isNull();
  }

  @Test
  void convertsSchemaWithNestedGroupsLogicalTypesAndIds() {
    MessageType schema = Types.buildMessage()
        .id(100)
        .required(PrimitiveTypeName.INT32)
        .id(1)
        .named("id")
        .optional(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .id(2)
        .named("name")
        .optional(PrimitiveTypeName.INT32)
        .as(LogicalTypeAnnotation.decimalType(2, 9))
        .id(3)
        .named("amount")
        .required(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY)
        .length(16)
        .as(LogicalTypeAnnotation.uuidType())
        .id(4)
        .named("uuid")
        .optional(PrimitiveTypeName.INT64)
        .as(LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MICROS))
        .id(5)
        .named("ts")
        .optionalGroup()
        .as(LogicalTypeAnnotation.mapType())
        .id(6)
        .required(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .named("key")
        .optional(PrimitiveTypeName.INT32)
        .named("value")
        .named("attributes")
        .named("root");

    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    List<SchemaElement> elements = converter.toParquetSchema(schema);

    assertThat(elements)
        .extracting(SchemaElement::getName)
        .containsExactly("root", "id", "name", "amount", "uuid", "ts", "attributes", "key", "value");
    SchemaElement root = elements.get(0);
    assertThat(root.getNum_children()).isEqualTo(6);

    SchemaElement id = elements.get(1);
    assertThat(id.getType()).isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(id.getRepetition_type()).isEqualTo(FieldRepetitionType.REQUIRED);
    assertThat(id.getField_id()).isEqualTo(1);

    SchemaElement name = elements.get(2);
    assertThat(name.getType()).isEqualTo(org.apache.parquet.format.Type.BYTE_ARRAY);
    assertThat(name.getConverted_type()).isEqualTo(ConvertedType.UTF8);
    assertThat(name.getLogicalType()).isEqualTo(LogicalTypes.UTF8);

    SchemaElement amount = elements.get(3);
    assertThat(amount.getConverted_type()).isEqualTo(ConvertedType.DECIMAL);
    assertThat(amount.getLogicalType().getSetField()).isEqualTo(LogicalType._Fields.DECIMAL);
    assertThat(amount.getLogicalType().getDECIMAL().getScale()).isEqualTo(2);
    assertThat(amount.getLogicalType().getDECIMAL().getPrecision()).isEqualTo(9);
    assertThat(amount.getScale()).isEqualTo(2);
    assertThat(amount.getPrecision()).isEqualTo(9);

    SchemaElement uuid = elements.get(4);
    assertThat(uuid.getType()).isEqualTo(org.apache.parquet.format.Type.FIXED_LEN_BYTE_ARRAY);
    assertThat(uuid.getType_length()).isEqualTo(16);
    assertThat(uuid.getLogicalType()).isEqualTo(LogicalTypes.UUID);

    SchemaElement timestamp = elements.get(5);
    assertThat(timestamp.getConverted_type()).isEqualTo(ConvertedType.TIMESTAMP_MICROS);
    assertThat(timestamp.getLogicalType().getSetField()).isEqualTo(LogicalType._Fields.TIMESTAMP);
    assertThat(timestamp.getLogicalType().getTIMESTAMP().isIsAdjustedToUTC())
        .isTrue();
    assertThat(timestamp.getLogicalType().getTIMESTAMP().getUnit().getSetField())
        .isEqualTo(org.apache.parquet.format.TimeUnit._Fields.MICROS);

    SchemaElement attributes = elements.get(6);
    assertThat(attributes.getNum_children()).isEqualTo(2);
    assertThat(attributes.getConverted_type()).isEqualTo(ConvertedType.MAP);
    assertThat(attributes.getLogicalType()).isEqualTo(LogicalTypes.MAP);
    assertThat(attributes.getField_id()).isEqualTo(6);
  }

  @Test
  void reconstructsSchemaAndHonorsSpecialColumnOrders() {
    MessageType schema = Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("id")
        .optional(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .named("name")
        .named("root");
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    List<SchemaElement> elements = converter.toParquetSchema(schema);

    MessageType roundTripped = converter.fromParquetSchema(elements, null);
    assertThat(roundTripped).isEqualTo(schema);
    assertThat(roundTripped.getType("name").getLogicalTypeAnnotation())
        .isEqualTo(LogicalTypeAnnotation.stringType());

    MessageType specialTypes = Types.buildMessage()
        .optional(PrimitiveTypeName.INT96)
        .named("legacyTimestamp")
        .optional(PrimitiveTypeName.FLOAT)
        .named("floatValue")
        .named("root");
    List<SchemaElement> specialElements = converter.toParquetSchema(specialTypes);
    org.apache.parquet.format.ColumnOrder typeDefined = new org.apache.parquet.format.ColumnOrder();
    typeDefined.setTYPE_ORDER(new TypeDefinedOrder());
    MessageType restored = converter.fromParquetSchema(specialElements, Arrays.asList(typeDefined, typeDefined));

    assertThat(restored.getType("legacyTimestamp")
            .asPrimitiveType()
            .columnOrder()
            .getColumnOrderName())
        .isEqualTo(ColumnOrderName.UNDEFINED);
    assertThat(restored.getType("floatValue")
            .asPrimitiveType()
            .columnOrder()
            .getColumnOrderName())
        .isEqualTo(ColumnOrderName.TYPE_DEFINED_ORDER);
  }

  @Test
  void convertsLogicalTypesAndConvertedTypes() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    assertLogicalType(converter, LogicalTypeAnnotation.stringType(), LogicalType._Fields.STRING);
    assertLogicalType(converter, LogicalTypeAnnotation.mapType(), LogicalType._Fields.MAP);
    assertLogicalType(converter, LogicalTypeAnnotation.listType(), LogicalType._Fields.LIST);
    assertLogicalType(converter, LogicalTypeAnnotation.enumType(), LogicalType._Fields.ENUM);
    assertLogicalType(converter, LogicalTypeAnnotation.dateType(), LogicalType._Fields.DATE);
    assertLogicalType(converter, LogicalTypeAnnotation.jsonType(), LogicalType._Fields.JSON);
    assertLogicalType(converter, LogicalTypeAnnotation.bsonType(), LogicalType._Fields.BSON);
    assertLogicalType(converter, LogicalTypeAnnotation.uuidType(), LogicalType._Fields.UUID);
    assertLogicalType(converter, LogicalTypeAnnotation.float16Type(), LogicalType._Fields.FLOAT16);
    assertLogicalType(converter, LogicalTypeAnnotation.unknownType(), LogicalType._Fields.UNKNOWN);
    assertLogicalType(converter, LogicalTypeAnnotation.intervalType(), LogicalType._Fields.UNKNOWN);
    assertLogicalType(converter, LogicalTypeAnnotation.variantType((byte) 2), LogicalType._Fields.VARIANT);

    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.stringType()))
        .isEqualTo(ConvertedType.UTF8);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.mapType()))
        .isEqualTo(ConvertedType.MAP);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.listType()))
        .isEqualTo(ConvertedType.LIST);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.enumType()))
        .isEqualTo(ConvertedType.ENUM);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.decimalType(2, 9)))
        .isEqualTo(ConvertedType.DECIMAL);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.dateType()))
        .isEqualTo(ConvertedType.DATE);
    assertThat(converter.convertToConvertedType(
            LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.MILLIS)))
        .isEqualTo(ConvertedType.TIME_MILLIS);
    assertThat(converter.convertToConvertedType(
            LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.MICROS)))
        .isEqualTo(ConvertedType.TIME_MICROS);
    assertThat(converter.convertToConvertedType(
            LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.NANOS)))
        .isNull();
    assertThat(converter.convertToConvertedType(
            LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MILLIS)))
        .isEqualTo(ConvertedType.TIMESTAMP_MILLIS);
    assertThat(converter.convertToConvertedType(
            LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MICROS)))
        .isEqualTo(ConvertedType.TIMESTAMP_MICROS);
    assertThat(converter.convertToConvertedType(
            LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.NANOS)))
        .isNull();
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.intType(8, true)))
        .isEqualTo(ConvertedType.INT_8);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.intType(16, false)))
        .isEqualTo(ConvertedType.UINT_16);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.intType(32, true)))
        .isEqualTo(ConvertedType.INT_32);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.intType(64, false)))
        .isEqualTo(ConvertedType.UINT_64);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.jsonType()))
        .isEqualTo(ConvertedType.JSON);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.bsonType()))
        .isEqualTo(ConvertedType.BSON);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.intervalType()))
        .isEqualTo(ConvertedType.INTERVAL);
    assertThat(converter.convertToConvertedType(LogicalTypeAnnotation.MapKeyValueTypeAnnotation.getInstance()))
        .isEqualTo(ConvertedType.MAP_KEY_VALUE);

    LogicalType time = converter.convertToLogicalType(
        LogicalTypeAnnotation.timeType(false, LogicalTypeAnnotation.TimeUnit.NANOS));
    assertThat(time.getTIME().isIsAdjustedToUTC()).isFalse();
    assertThat(time.getTIME().getUnit().getSetField()).isEqualTo(org.apache.parquet.format.TimeUnit._Fields.NANOS);

    LogicalType geometry = converter.convertToLogicalType(LogicalTypeAnnotation.geometryType("OGC:CRS84"));
    assertThat(geometry.getGEOMETRY().getCrs()).isEqualTo("OGC:CRS84");

    LogicalType geography = converter.convertToLogicalType(LogicalTypeAnnotation.geographyType(
        "OGC:CRS84", org.apache.parquet.column.schema.EdgeInterpolationAlgorithm.KARNEY));
    assertThat(geography.getGEOGRAPHY().getCrs()).isEqualTo("OGC:CRS84");
    assertThat(geography.getGEOGRAPHY().getAlgorithm())
        .isEqualTo(org.apache.parquet.format.EdgeInterpolationAlgorithm.KARNEY);

    LogicalType variant = converter.convertToLogicalType(LogicalTypeAnnotation.variantType((byte) 3));
    assertThat(variant.getVARIANT().getSpecification_version()).isEqualTo((byte) 3);
  }

  private static void assertLogicalType(
      ParquetMetadataConverter converter, LogicalTypeAnnotation annotation, LogicalType._Fields expectedField) {
    assertThat(converter.convertToLogicalType(annotation).getSetField()).isEqualTo(expectedField);
  }

  @Test
  void convertsStatisticsWithV2ValuesNullAndNanCounts() {
    PrimitiveType type = Types.required(PrimitiveTypeName.INT32).named("id");
    Statistics<?> stats = Statistics.createStats(type);
    stats.updateStats(5);
    stats.updateStats(2);
    stats.setNumNulls(3);
    stats.incrementNanCount(4);

    org.apache.parquet.format.Statistics formatStats = ParquetMetadataConverter.toParquetStatistics(stats);
    assertThat(formatStats.getNull_count()).isEqualTo(3L);
    assertThat(formatStats.getNan_count()).isEqualTo(4L);
    assertThat(formatStats.isSetMin()).isTrue();
    assertThat(formatStats.isSetMax()).isTrue();
    assertThat(formatStats.getMin()).containsExactly(BytesUtils.intToBytes(2));
    assertThat(formatStats.getMax()).containsExactly(BytesUtils.intToBytes(5));
    assertThat(formatStats.getMin_value()).containsExactly(BytesUtils.intToBytes(2));
    assertThat(formatStats.getMax_value()).containsExactly(BytesUtils.intToBytes(5));

    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    Statistics<?> restored = converter.fromParquetStatistics(CREATED_BY, formatStats, type);
    assertThat(restored.hasNonNullValue()).isTrue();
    assertThat(restored.getMinBytes()).containsExactly(BytesUtils.intToBytes(2));
    assertThat(restored.getMaxBytes()).containsExactly(BytesUtils.intToBytes(5));
    assertThat(restored.getNumNulls()).isEqualTo(3);
    assertThat(restored.getNanCount()).isEqualTo(4);
    assertThat(restored.isNanCountSet()).isTrue();
  }

  @Test
  void fromParquetStatisticsDropsLegacyUnsignedMinMaxAndKeepsOtherFields() {
    PrimitiveType type = Types.required(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .named("name");
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    org.apache.parquet.format.Statistics legacy = new org.apache.parquet.format.Statistics();
    legacy.setMin(org.apache.parquet.io.api.Binary.fromString("a").getBytes());
    legacy.setMax(org.apache.parquet.io.api.Binary.fromString("z").getBytes());
    legacy.setNull_count(2);
    Statistics<?> restored = converter.fromParquetStatistics(CREATED_BY, legacy, type);
    assertThat(restored.hasNonNullValue()).isFalse();
    assertThat(restored.getNumNulls()).isEqualTo(2);

    org.apache.parquet.format.Statistics equalValues = new org.apache.parquet.format.Statistics();
    equalValues.setMin(org.apache.parquet.io.api.Binary.fromString("same").getBytes());
    equalValues.setMax(org.apache.parquet.io.api.Binary.fromString("same").getBytes());
    Statistics<?> equalRestored = converter.fromParquetStatistics(CREATED_BY, equalValues, type);
    assertThat(equalRestored.hasNonNullValue()).isTrue();
    assertThat(equalRestored.getMinBytes())
        .containsExactly(
            org.apache.parquet.io.api.Binary.fromString("same").getBytes());
  }

  @Test
  void signedStringMinMaxModeAcceptsLegacyMinMax() {
    PrimitiveType type = Types.required(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .named("name");
    org.apache.parquet.format.Statistics legacy = new org.apache.parquet.format.Statistics();
    legacy.setMin(org.apache.parquet.io.api.Binary.fromString("a").getBytes());
    legacy.setMax(org.apache.parquet.io.api.Binary.fromString("z").getBytes());

    Configuration conf = new Configuration(false);
    conf.setBoolean("parquet.strings.signed-min-max.enabled", true);
    ParquetMetadataConverter fromConf = new ParquetMetadataConverter(conf);
    assertThat(fromConf.fromParquetStatistics(CREATED_BY, legacy, type).hasNonNullValue())
        .isTrue();

    ParquetMetadataConverter fromOptions = new ParquetMetadataConverter(
        ParquetReadOptions.builder().useSignedStringMinMax().build());
    assertThat(fromOptions.fromParquetStatistics(CREATED_BY, legacy, type).hasNonNullValue())
        .isTrue();
  }

  @Test
  void truncatesOrSkipsLargeBinaryStatistics() {
    PrimitiveType type = Types.required(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .named("name");

    Statistics<?> stats = Statistics.createStats(type);
    stats.updateStats(org.apache.parquet.io.api.Binary.fromString("a".repeat(200)));
    stats.updateStats(org.apache.parquet.io.api.Binary.fromString("z".repeat(200)));
    org.apache.parquet.format.Statistics truncated = ParquetMetadataConverter.toParquetStatistics(stats, 8);
    assertThat(truncated.isSetMin_value()).isTrue();
    assertThat(truncated.isSetMax_value()).isTrue();
    assertThat(truncated.getMin_value().length).isLessThanOrEqualTo(8);
    assertThat(truncated.getMax_value().length).isLessThanOrEqualTo(8);
    assertThat(truncated.isSetMin()).isFalse();
    assertThat(truncated.isSetMax()).isFalse();

    Statistics<?> huge = Statistics.createStats(type);
    huge.updateStats(org.apache.parquet.io.api.Binary.fromString("a".repeat(5000)));
    huge.updateStats(org.apache.parquet.io.api.Binary.fromString("z".repeat(5000)));
    huge.setNumNulls(1);
    org.apache.parquet.format.Statistics omitted =
        ParquetMetadataConverter.toParquetStatistics(huge, Integer.MAX_VALUE);
    assertThat(omitted.isSetMin()).isFalse();
    assertThat(omitted.isSetMax()).isFalse();
    assertThat(omitted.isSetMin_value()).isFalse();
    assertThat(omitted.isSetMax_value()).isFalse();
    assertThat(omitted.isSetNull_count()).isFalse();

    Statistics<?> nullOnly = Statistics.createStats(type);
    nullOnly.setNumNulls(9);
    org.apache.parquet.format.Statistics nullOnlyFormat = ParquetMetadataConverter.toParquetStatistics(nullOnly);
    assertThat(nullOnlyFormat.getNull_count()).isEqualTo(9);
    assertThat(nullOnlyFormat.isSetMin()).isFalse();
    assertThat(nullOnlyFormat.isSetMax()).isFalse();
  }

