  @Test
  void rejectsOverlappingBlockPositionsWhenWritingMetadata() {
    MessageType schema = Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("id")
        .named("root");
    PrimitiveType type = schema.getType("id").asPrimitiveType();
    BlockMetaData first = blockAtOffset(type, 4L, 100L, 1);
    BlockMetaData second = blockAtOffset(type, 50L, 100L, 2);
    ParquetMetadata metadata = new ParquetMetadata(
        new org.apache.parquet.hadoop.metadata.FileMetaData(schema, Collections.emptyMap(), CREATED_BY),
        Arrays.asList(first, second));

