  private static BlockMetaData blockAtOffset(PrimitiveType type, long dataPageOffset, long totalSize, int rowCount) {
    Statistics<?> stats = Statistics.createStats(type);
    ColumnChunkMetaData column = ColumnChunkMetaData.get(
        org.apache.parquet.hadoop.metadata.ColumnPath.get("id"),
        type,
        CompressionCodecName.UNCOMPRESSED,
        null,
        new LinkedHashSet<>(Collections.singletonList(Encoding.PLAIN)),
        stats,
        dataPageOffset,
        -1L,
        rowCount,
        totalSize,
        totalSize);
    BlockMetaData block = new BlockMetaData();
    block.setRowCount(rowCount);
    block.setTotalByteSize(totalSize);
    block.addColumn(column);
    return block;
  }

  @Test
  void readParquetMetadataAppliesOffsetAndRangeFilters() throws IOException {
    byte[] serialized = serialize(rowGroupMetadata());
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    ParquetMetadata all = converter.readParquetMetadata(new ByteArrayInputStream(serialized));
    assertThat(all.getBlocks()).hasSize(3);
    assertThat(all.getBlocks()).extracting(BlockMetaData::getRowCount).containsExactly(10L, 20L, 30L);
    assertThat(all.getBlocks()).extracting(BlockMetaData::getRowIndexOffset).containsExactly(0L, 10L, 30L);

    ParquetMetadata skipped = converter.readParquetMetadata(
        new ByteArrayInputStream(serialized), ParquetMetadataConverter.SKIP_ROW_GROUPS);
    assertThat(skipped.getBlocks()).isEmpty();
    assertThat(skipped.getFileMetaData().getSchema().getName()).isEqualTo("root");

    ParquetMetadata byOffset = converter.readParquetMetadata(
        new ByteArrayInputStream(serialized), ParquetMetadataConverter.offsets(200L));
    assertThat(byOffset.getBlocks()).hasSize(1);
    assertThat(byOffset.getBlocks().get(0).getRowCount()).isEqualTo(20L);
    assertThat(byOffset.getBlocks().get(0).getRowIndexOffset()).isEqualTo(10L);
    assertThat(byOffset.getBlocks().get(0).getColumns().get(0).getFirstDataPageOffset())
        .isEqualTo(200L);

    ParquetMetadata byRange = converter.readParquetMetadata(
        new ByteArrayInputStream(serialized), ParquetMetadataConverter.range(240L, 360L));
    assertThat(byRange.getBlocks()).hasSize(2);
    assertThat(byRange.getBlocks()).extracting(BlockMetaData::getRowCount).containsExactly(20L, 30L);
    assertThat(byRange.getBlocks())
        .extracting(BlockMetaData::getRowIndexOffset)
        .containsExactly(10L, 30L);
  }

  private static FileMetaData rowGroupMetadata() {
    List<SchemaElement> schema = new ArrayList<>();
    SchemaElement root = new SchemaElement("root");
    root.setNum_children(1);
    SchemaElement id = new SchemaElement("id");
    id.setType(org.apache.parquet.format.Type.INT32);
    id.setRepetition_type(FieldRepetitionType.REQUIRED);
    schema.add(root);
    schema.add(id);

    List<RowGroup> rowGroups = new ArrayList<>();
    long rows = 10;
    for (int i = 0; i < 3; i++) {
      long offset = 100L + i * 100L;
      ColumnMetaData columnMetaData = new ColumnMetaData(
          org.apache.parquet.format.Type.INT32,
          Collections.singletonList(org.apache.parquet.format.Encoding.PLAIN),
          Collections.singletonList("id"),
          CompressionCodec.UNCOMPRESSED,
          rows,
          150L,
          100L,
          offset);
      org.apache.parquet.format.ColumnChunk chunk = new org.apache.parquet.format.ColumnChunk(0L);
      chunk.setMeta_data(columnMetaData);
      RowGroup rowGroup = new RowGroup(Collections.singletonList(chunk), 150L, rows);
      rowGroup.setFile_offset(offset);
      rowGroup.setTotal_compressed_size(100L);
      rowGroup.setOrdinal((short) i);
      rowGroups.add(rowGroup);
      rows += 10;
    }

    FileMetaData fileMetaData = new FileMetaData(1, schema, 60L, rowGroups);
    fileMetaData.setCreated_by(CREATED_BY);
    return fileMetaData;
  }

  private static byte[] serialize(FileMetaData metadata) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    Util.writeFileMetaData(metadata, out);
    return out.toByteArray();
  }

  @Test
  void startOffsetFilterHandlesRowGroupsWithoutColumnMetadata() {
    RowGroup first = rowGroupWithoutColumnMetadata(4L, 100L, 10L, (short) 0);
    RowGroup second = rowGroupWithoutColumnMetadata(110L, 100L, 20L, (short) 1);
    FileMetaData metadata = metadataWithRowGroups(first, second);

    ParquetMetadataConverter.OffsetMetadataFilter filter =
        (ParquetMetadataConverter.OffsetMetadataFilter) ParquetMetadataConverter.offsets(110L);
    FileMetaData filtered = ParquetMetadataConverter.filterFileMetaDataByStart(metadata, filter);
    assertThat(filtered.getRow_groups()).containsExactly(second);

    FileMetaData corrupt = metadataWithRowGroups(
        rowGroupWithoutColumnMetadata(4L, 100L, 10L, (short) 0),
        rowGroupWithoutColumnMetadata(50L, 100L, 20L, (short) 1));
    assertThatThrownBy(() -> ParquetMetadataConverter.filterFileMetaDataByStart(
            corrupt, (ParquetMetadataConverter.OffsetMetadataFilter) ParquetMetadataConverter.offsets(50L)))
        .isInstanceOf(InvalidFileOffsetException.class)
        .hasMessageContaining("corrupted RowGroup.file_offset found");
  }

  private static RowGroup rowGroupWithoutColumnMetadata(
      long fileOffset, long compressedSize, long rowCount, short ordinal) {
    RowGroup rowGroup = new RowGroup(
        Collections.singletonList(new org.apache.parquet.format.ColumnChunk(0L)), compressedSize, rowCount);
    rowGroup.setFile_offset(fileOffset);
    rowGroup.setTotal_compressed_size(compressedSize);
    rowGroup.setOrdinal(ordinal);
    return rowGroup;
  }

  private static FileMetaData metadataWithRowGroups(RowGroup... rowGroups) {
    List<SchemaElement> schema = new ArrayList<>();
    SchemaElement root = new SchemaElement("root");
    root.setNum_children(1);
    SchemaElement id = new SchemaElement("id");
    id.setType(org.apache.parquet.format.Type.INT32);
    id.setRepetition_type(FieldRepetitionType.REQUIRED);
    schema.add(root);
    schema.add(id);
    return new FileMetaData(1, schema, 30L, Arrays.asList(rowGroups));
  }

