  @Test
  void writesDataPageV1HeadersWithAndWithoutCrc() throws IOException {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    ByteArrayOutputStream withCrc = new ByteArrayOutputStream();
    converter.writeDataPageV1Header(100, 80, 12, Encoding.RLE, Encoding.BIT_PACKED, Encoding.PLAIN, 12345, withCrc);

    PageHeader header = Util.readPageHeader(new ByteArrayInputStream(withCrc.toByteArray()));
    assertThat(header.getType()).isEqualTo(PageType.DATA_PAGE);
    assertThat(header.getUncompressed_page_size()).isEqualTo(100);
    assertThat(header.getCompressed_page_size()).isEqualTo(80);
    assertThat(header.getCrc()).isEqualTo(12345);
    assertThat(header.getData_page_header().getNum_values()).isEqualTo(12);
    assertThat(header.getData_page_header().getRepetition_level_encoding())
        .isEqualTo(org.apache.parquet.format.Encoding.RLE);
    assertThat(header.getData_page_header().getDefinition_level_encoding())
        .isEqualTo(org.apache.parquet.format.Encoding.BIT_PACKED);
    assertThat(header.getData_page_header().getEncoding()).isEqualTo(org.apache.parquet.format.Encoding.PLAIN);

    ByteArrayOutputStream withoutCrc = new ByteArrayOutputStream();
    converter.writeDataPageV1Header(
        50, 40, 3, Encoding.RLE, Encoding.RLE, Encoding.DELTA_BINARY_PACKED, withoutCrc);
    PageHeader noCrcHeader = Util.readPageHeader(new ByteArrayInputStream(withoutCrc.toByteArray()));
    assertThat(noCrcHeader.isSetCrc()).isFalse();
    assertThat(noCrcHeader.getData_page_header().getEncoding())
        .isEqualTo(org.apache.parquet.format.Encoding.DELTA_BINARY_PACKED);
  }

