    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    org.apache.parquet.column.statistics.geospatial.BoundingBox boundingBox =
        new org.apache.parquet.column.statistics.geospatial.BoundingBox(
            -10, 10, -20, 20, -5, 5, Double.NaN, Double.NaN);
    org.apache.parquet.column.statistics.geospatial.GeospatialTypes geospatialTypes =
        new org.apache.parquet.column.statistics.geospatial.GeospatialTypes(
            new HashSet<>(Arrays.asList(5001, 1001)));
    org.apache.parquet.column.statistics.geospatial.GeospatialStatistics stats =
        new org.apache.parquet.column.statistics.geospatial.GeospatialStatistics(boundingBox, geospatialTypes);

    org.apache.parquet.format.GeospatialStatistics formatStats = converter.toParquetGeospatialStatistics(stats);
    assertThat(formatStats.getBbox().getXmin()).isEqualTo(-10);
    assertThat(formatStats.getBbox().getXmax()).isEqualTo(10);
    assertThat(formatStats.getBbox().getYmin()).isEqualTo(-20);
    assertThat(formatStats.getBbox().getYmax()).isEqualTo(20);
    assertThat(formatStats.getBbox().getZmin()).isEqualTo(-5);
    assertThat(formatStats.getBbox().getZmax()).isEqualTo(5);
    assertThat(formatStats.getBbox().isSetMmin()).isFalse();
    assertThat(formatStats.getGeospatial_types()).containsExactly(1001, 5001);

