    assertThat(restored.getGeospatialTypes().getTypes()).containsExactlyInAnyOrder(1001, 5001);

    assertThat(converter.toParquetGeospatialStatistics(null)).isNull();
    assertThat(converter.toParquetGeospatialStatistics(
