  @Test
  void convertsThriftLogicalTypesToAnnotations() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.UTF8)).isEqualTo(LogicalTypeAnnotation.stringType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.MAP)).isEqualTo(LogicalTypeAnnotation.mapType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.LIST)).isEqualTo(LogicalTypeAnnotation.listType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.ENUM)).isEqualTo(LogicalTypeAnnotation.enumType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.DATE)).isEqualTo(LogicalTypeAnnotation.dateType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.JSON)).isEqualTo(LogicalTypeAnnotation.jsonType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.BSON)).isEqualTo(LogicalTypeAnnotation.bsonType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.UUID)).isEqualTo(LogicalTypeAnnotation.uuidType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.FLOAT16))
        .isEqualTo(LogicalTypeAnnotation.float16Type());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.UNKNOWN))
        .isEqualTo(LogicalTypeAnnotation.unknownType());
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.DECIMAL(2, 9)))
        .isEqualTo(LogicalTypeAnnotation.decimalType(2, 9));
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.INT_16))
        .isEqualTo(LogicalTypeAnnotation.intType(16, true));
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.UINT_32))
        .isEqualTo(LogicalTypeAnnotation.intType(32, false));
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.TIME_MILLIS))
        .isEqualTo(LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.MILLIS));
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.TIMESTAMP_MICROS))
        .isEqualTo(LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MICROS));
    assertThat(converter.getLogicalTypeAnnotation(LogicalType.TIME(new org.apache.parquet.format.TimeType(
            false, org.apache.parquet.format.TimeUnit.NANOS(new org.apache.parquet.format.NanoSeconds())))))
        .isEqualTo(LogicalTypeAnnotation.timeType(false, LogicalTypeAnnotation.TimeUnit.NANOS));
    assertThat(converter.getLogicalTypeAnnotation(LogicalType.TIMESTAMP(
            new org.apache.parquet.format.TimestampType(false, LogicalTypes.TimeUnits.MILLIS))))
        .isEqualTo(LogicalTypeAnnotation.timestampType(false, LogicalTypeAnnotation.TimeUnit.MILLIS));
    org.apache.parquet.format.GeometryType geometryType = new org.apache.parquet.format.GeometryType();
    geometryType.setCrs("OGC:CRS84");
    assertThat(converter.getLogicalTypeAnnotation(LogicalType.GEOMETRY(geometryType)))
        .isEqualTo(LogicalTypeAnnotation.geometryType("OGC:CRS84"));

    org.apache.parquet.format.GeographyType geographyType = new org.apache.parquet.format.GeographyType();
    geographyType.setCrs("OGC:CRS84");
    geographyType.setAlgorithm(org.apache.parquet.format.EdgeInterpolationAlgorithm.ANDOYER);
    assertThat(converter.getLogicalTypeAnnotation(LogicalType.GEOGRAPHY(geographyType)))
        .isEqualTo(LogicalTypeAnnotation.geographyType(
            "OGC:CRS84", org.apache.parquet.column.schema.EdgeInterpolationAlgorithm.ANDOYER));
    assertThat(converter.getLogicalTypeAnnotation(LogicalTypes.VARIANT((byte) 4)))
        .isEqualTo(LogicalTypeAnnotation.variantType((byte) 4));
    assertThat(converter.getLogicalTypeAnnotation(new LogicalType())).isNull();
    assertThat(converter.getLogicalTypeAnnotation(LogicalType.FILE(new org.apache.parquet.format.FileType())))
        .isNull();
  }

