  @Test
  void roundTripsColumnIndexes() {
    PrimitiveType type = Types.required(PrimitiveTypeName.INT32).named("id");
    ByteBuffer min = ByteBuffer.wrap(BytesUtils.intToBytes(10));
    ByteBuffer max = ByteBuffer.wrap(BytesUtils.intToBytes(20));
    org.apache.parquet.internal.column.columnindex.ColumnIndex columnIndex =
        org.apache.parquet.internal.column.columnindex.ColumnIndexBuilder.build(
            type,
            org.apache.parquet.internal.column.columnindex.BoundaryOrder.ASCENDING,
            Collections.singletonList(false),
            Collections.singletonList(2L),
            Collections.singletonList(1L),
            Collections.singletonList(min),
            Collections.singletonList(max),
            Arrays.asList(1L, 2L),
            Arrays.asList(0L, 3L));

    ColumnIndex parquetColumnIndex = ParquetMetadataConverter.toParquetColumnIndex(type, columnIndex);
    assertThat(parquetColumnIndex).isNotNull();
    assertThat(parquetColumnIndex.getNull_pages()).containsExactly(false);
    assertThat(parquetColumnIndex.getNull_counts()).containsExactly(2L);
    assertThat(parquetColumnIndex.getNan_counts()).containsExactly(1L);
    assertThat(parquetColumnIndex.getMin_values()).containsExactly(min);
    assertThat(parquetColumnIndex.getMax_values()).containsExactly(max);
    assertThat(parquetColumnIndex.getBoundary_order()).isEqualTo(org.apache.parquet.format.BoundaryOrder.ASCENDING);
    assertThat(parquetColumnIndex.getRepetition_level_histograms()).containsExactly(1L, 2L);
    assertThat(parquetColumnIndex.getDefinition_level_histograms()).containsExactly(0L, 3L);

    org.apache.parquet.internal.column.columnindex.ColumnIndex restored =
        ParquetMetadataConverter.fromParquetColumnIndex(type, parquetColumnIndex);
    assertThat(restored.getNullPages()).containsExactly(false);
    assertThat(restored.getNullCounts()).containsExactly(2L);
    assertThat(restored.getNanCounts()).containsExactly(1L);
    assertThat(restored.getMinValues()).containsExactly(min);
    assertThat(restored.getMaxValues()).containsExactly(max);
    assertThat(restored.getBoundaryOrder())
        .isEqualTo(org.apache.parquet.internal.column.columnindex.BoundaryOrder.ASCENDING);
    assertThat(restored.getRepetitionLevelHistogram()).containsExactly(1L, 2L);
    assertThat(restored.getDefinitionLevelHistogram()).containsExactly(0L, 3L);

    assertThat(ParquetMetadataConverter.toParquetColumnIndex(type, null)).isNull();
  }

