  @Test
  void roundTripsOffsetIndexesAndOptionalUnencodedByteCounts() {
    org.apache.parquet.internal.column.columnindex.OffsetIndexBuilder builder =
        org.apache.parquet.internal.column.columnindex.OffsetIndexBuilder.getBuilder();
    builder.add(100L, 50, 0L, Optional.of(11L));
    builder.add(200L, 60, 10L, Optional.of(22L));
    org.apache.parquet.internal.column.columnindex.OffsetIndex index = builder.build();

    OffsetIndex parquetIndex = ParquetMetadataConverter.toParquetOffsetIndex(index);
    assertThat(parquetIndex.getPage_locations())
        .extracting(
            PageLocation::getOffset,
            PageLocation::getCompressed_page_size,
            PageLocation::getFirst_row_index)
        .containsExactly(
            org.assertj.core.groups.Tuple.tuple(100L, 50, 0L),
            org.assertj.core.groups.Tuple.tuple(200L, 60, 10L));
    assertThat(parquetIndex.getUnencoded_byte_array_data_bytes()).containsExactly(11L, 22L);

    org.apache.parquet.internal.column.columnindex.OffsetIndex restored =
        ParquetMetadataConverter.fromParquetOffsetIndex(parquetIndex);
    assertThat(restored.getPageCount()).isEqualTo(2);
    assertThat(restored.getOffset(0)).isEqualTo(100L);
    assertThat(restored.getCompressedPageSize(0)).isEqualTo(50);
    assertThat(restored.getFirstRowIndex(0)).isZero();
    assertThat(restored.getUnencodedByteArrayDataBytes(0)).contains(11L);
    assertThat(restored.getOffset(1)).isEqualTo(200L);
    assertThat(restored.getUnencodedByteArrayDataBytes(1)).contains(22L);

    org.apache.parquet.internal.column.columnindex.OffsetIndexBuilder noUnencodedBuilder =
        org.apache.parquet.internal.column.columnindex.OffsetIndexBuilder.getBuilder();
    noUnencodedBuilder.add(300L, 70, 20L);
    org.apache.parquet.internal.column.columnindex.OffsetIndex noUnencoded = noUnencodedBuilder.build();
    OffsetIndex parquetNoUnencoded = ParquetMetadataConverter.toParquetOffsetIndex(noUnencoded);
    assertThat(parquetNoUnencoded.isSetUnencoded_byte_array_data_bytes()).isFalse();
    org.apache.parquet.internal.column.columnindex.OffsetIndex restoredNoUnencoded =
        ParquetMetadataConverter.fromParquetOffsetIndex(parquetNoUnencoded);
    assertThat(restoredNoUnencoded.getUnencodedByteArrayDataBytes(0)).isEmpty();
  }

