    SizeStatistics stats = new SizeStatistics(type, 99L, Arrays.asList(5L, 6L), Arrays.asList(1L, 2L, 3L));

    org.apache.parquet.format.SizeStatistics formatStats = ParquetMetadataConverter.toParquetSizeStatistics(stats);
