    SizeStatistics restored = ParquetMetadataConverter.fromParquetSizeStatistics(formatStats, type);
    assertThat(restored.getType()).isEqualTo(type);
    assertThat(restored.getUnencodedByteArrayDataBytes()).contains(99L);
    assertThat(restored.getRepetitionLevelHistogram()).containsExactly(5L, 6L);
    assertThat(restored.getDefinitionLevelHistogram()).containsExactly(1L, 2L, 3L);

    assertThat(ParquetMetadataConverter.toParquetSizeStatistics(null)).isNull();
    assertThat(ParquetMetadataConverter.fromParquetSizeStatistics(null, type))
        .isNull();
  }

  @Test
  void convertsGeospatialStatisticsAndSortsTypeCodes() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    org.apache.parquet.column.statistics.geospatial.BoundingBox boundingBox =
        new org.apache.parquet.column.statistics.geospatial.BoundingBox(
            -10, 10, -20, 20, -5, 5, Double.NaN, Double.NaN);
    org.apache.parquet.column.statistics.geospatial.GeospatialTypes geospatialTypes =
        new org.apache.parquet.column.statistics.geospatial.GeospatialTypes(
            new HashSet<>(Arrays.asList(5001, 1001)));
    org.apache.parquet.column.statistics.geospatial.GeospatialStatistics stats =
        new org.apache.parquet.column.statistics.geospatial.GeospatialStatistics(boundingBox, geospatialTypes);

    org.apache.parquet.format.GeospatialStatistics formatStats = converter.toParquetGeospatialStatistics(stats);
    assertThat(formatStats.getBbox().getXmin()).isEqualTo(-10);
    assertThat(formatStats.getBbox().getXmax()).isEqualTo(10);
    assertThat(formatStats.getBbox().getYmin()).isEqualTo(-20);
    assertThat(formatStats.getBbox().getYmax()).isEqualTo(20);
    assertThat(formatStats.getBbox().getZmin()).isEqualTo(-5);
    assertThat(formatStats.getBbox().getZmax()).isEqualTo(5);
    assertThat(formatStats.getBbox().isSetMmin()).isFalse();
    assertThat(formatStats.getGeospatial_types()).containsExactly(1001, 5001);

    PrimitiveType type = Types.optional(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.geometryType("OGC:CRS84"))
        .named("geometry");
    org.apache.parquet.column.statistics.geospatial.GeospatialStatistics restored =
        ParquetMetadataConverter.fromParquetStatistics(formatStats, type);
    assertThat(restored).isNotNull();
    assertThat(restored.getBoundingBox().getXMin()).isEqualTo(-10);
    assertThat(restored.getBoundingBox().getZMax()).isEqualTo(5);
    assertThat(restored.getGeospatialTypes().getTypes()).containsExactlyInAnyOrder(1001, 5001);

    assertThat(converter.toParquetGeospatialStatistics(null)).isNull();
    assertThat(converter.toParquetGeospatialStatistics(
            new org.apache.parquet.column.statistics.geospatial.GeospatialStatistics()))
        .isNull();
  }

