  @Test
  void buildsColumnChunkMetadataFromThriftMetadata() {
    PrimitiveType type = Types.required(PrimitiveTypeName.INT32).named("id");
    org.apache.parquet.format.Statistics formatStats = new org.apache.parquet.format.Statistics();
    formatStats.setMin_value(BytesUtils.intToBytes(2));
    formatStats.setMax_value(BytesUtils.intToBytes(8));
    formatStats.setNull_count(4);
    ColumnMetaData metadata = new ColumnMetaData(
        org.apache.parquet.format.Type.INT32,
        Arrays.asList(org.apache.parquet.format.Encoding.PLAIN, org.apache.parquet.format.Encoding.RLE),
        Collections.singletonList("id"),
        CompressionCodec.GZIP,
        9L,
        90L,
        80L,
        40L);
    metadata.setStatistics(formatStats);
    metadata.setDictionary_page_offset(20L);

    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    ColumnChunkMetaData column = converter.buildColumnChunkMetaData(
        metadata, org.apache.parquet.hadoop.metadata.ColumnPath.get("id"), type, CREATED_BY);
    assertThat(column.getPath().toDotString()).isEqualTo("id");
    assertThat(column.getCodec()).isEqualTo(CompressionCodecName.GZIP);
    assertThat(column.getValueCount()).isEqualTo(9L);
    assertThat(column.getTotalSize()).isEqualTo(80L);
    assertThat(column.getTotalUncompressedSize()).isEqualTo(90L);
    assertThat(column.getFirstDataPageOffset()).isEqualTo(40L);
    assertThat(column.getDictionaryPageOffset()).isEqualTo(20L);
    assertThat(column.getStatistics().getMinBytes()).containsExactly(BytesUtils.intToBytes(2));
    assertThat(column.getStatistics().getMaxBytes()).containsExactly(BytesUtils.intToBytes(8));
    assertThat(column.getStatistics().getNumNulls()).isEqualTo(4);
    assertThat(column.getEncodings()).containsExactlyInAnyOrder(Encoding.PLAIN, Encoding.RLE);
  }

  @Test
