    org.apache.parquet.format.Statistics statistics = new org.apache.parquet.format.Statistics();
    statistics.setMin_value(BytesUtils.intToBytes(3));
    statistics.setMax_value(BytesUtils.intToBytes(9));
    statistics.setNull_count(1);

    Statistics<?> withoutCreatedBy =
        ParquetMetadataConverter.fromParquetStatistics(statistics, PrimitiveTypeName.INT32);
