  }

  @Test
  void rangeFilterHandlesRowGroupsWithoutColumnMetadata() {
    FileMetaData metadata = metadataWithRowGroups(
        rowGroupWithoutColumnMetadata(4L, 100L, 10L, (short) 0),
        rowGroupWithoutColumnMetadata(110L, 100L, 20L, (short) 1),
        rowGroupWithoutColumnMetadata(210L, 100L, 30L, (short) 2));

    FileMetaData filtered = ParquetMetadataConverter.filterFileMetaDataByMidpoint(
        metadata, (ParquetMetadataConverter.RangeMetadataFilter) ParquetMetadataConverter.range(150L, 300L));
    assertThat(filtered.getRow_groups()).hasSize(2);
    assertThat(filtered.getRow_groups()).extracting(RowGroup::getNum_rows).containsExactly(20L, 30L);

    FileMetaData invalidFirstOffset = metadataWithRowGroups(
        rowGroupWithoutColumnMetadata(10L, 100L, 10L, (short) 0),
        rowGroupWithoutColumnMetadata(110L, 100L, 20L, (short) 1));
    FileMetaData repaired = ParquetMetadataConverter.filterFileMetaDataByMidpoint(
        invalidFirstOffset,
        (ParquetMetadataConverter.RangeMetadataFilter) ParquetMetadataConverter.range(0L, 100L));
    assertThat(repaired.getRow_groups())
        .containsExactly(invalidFirstOffset.getRow_groups().get(0));
  }

  @Test
  void writesDeprecatedDataPageHeaderOverloads() throws IOException {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    Statistics<?> stats =
        Statistics.createStats(Types.required(PrimitiveTypeName.INT32).named("id"));

    ByteArrayOutputStream v1 = new ByteArrayOutputStream();
    converter.writeDataPageHeader(90, 70, 11, stats, Encoding.RLE, Encoding.RLE, Encoding.PLAIN, v1);
    PageHeader v1Header = Util.readPageHeader(new ByteArrayInputStream(v1.toByteArray()));
    assertThat(v1Header.getType()).isEqualTo(PageType.DATA_PAGE);
    assertThat(v1Header.getData_page_header().getNum_values()).isEqualTo(11);
    assertThat(v1Header.getData_page_header().getEncoding()).isEqualTo(org.apache.parquet.format.Encoding.PLAIN);

    ByteArrayOutputStream v2 = new ByteArrayOutputStream();
    converter.writeDataPageV2Header(90, 70, 11, 1, 10, stats, Encoding.DELTA_BINARY_PACKED, 5, 6, v2);
    PageHeader v2Header = Util.readPageHeader(new ByteArrayInputStream(v2.toByteArray()));
    assertThat(v2Header.getType()).isEqualTo(PageType.DATA_PAGE_V2);
    assertThat(v2Header.getData_page_header_v2().getNum_nulls()).isEqualTo(1);
    assertThat(v2Header.getData_page_header_v2().getNum_rows()).isEqualTo(10);
    assertThat(v2Header.getData_page_header_v2().getEncoding())
        .isEqualTo(org.apache.parquet.format.Encoding.DELTA_BINARY_PACKED);
    assertThat(v2Header.getData_page_header_v2().isIs_compressed()).isTrue();
  }

